"""A filesystem jail for user scripts, built on CPython audit hooks (PEP 578).

The app runs user code in its own process, so `os` and `open` reach the whole
app sandbox: the activation key in ``shared_prefs``, every other project, the
signing material. Kotlin's ``Workspace.resolve`` cannot help here because the
Python side never goes through it. What can help is the interpreter itself:
since 3.8 every security-relevant operation raises an audit event, and a hook
added with :func:`sys.addaudithook` can veto it before it happens.

What this is not: a kernel-level jail. There is no second process and no
different uid, so only *Python-level* escapes are closed. In particular native
code reached through :mod:`ctypes` would be free to do anything, so every
``ctypes.*`` event is refused. That is deliberate: ctypes in a script is never
innocent and the standard library needs none of it.

The hook is installed once and stays installed (CPython has no
``removeaudithook``); it does nothing until a :class:`Jail` is active.
"""

import os
import sys

__all__ = ["SandboxViolation", "Jail", "intercept", "interpreter_roots"]


def interpreter_roots():
    """Directories holding the interpreter itself: stdlib, pip packages, us.

    Chaquopy unpacks all of them into the app's data directory, so a script must
    be able to read them while staying out of everything else the app stores
    there (the activation key in shared_prefs, other projects).
    """
    roots = []
    try:
        import sysconfig

        for value in sysconfig.get_paths().values():
            if value:
                roots.append(value)
    except Exception:  # sysconfig is present in every CPython, but never bet on it
        pass
    for module in (os, sys.modules.get("json"), sys.modules.get("pocketrun_sandbox")):
        path = getattr(module, "__file__", None)
        if path:
            roots.append(os.path.dirname(os.path.abspath(path)))
    if getattr(sys, "prefix", None):
        roots.append(sys.prefix)
    seen = []
    for root in roots:
        real = _abs_real(root)
        if real not in seen and os.path.isdir(real):
            seen.append(real)
    return seen


class SandboxViolation(BaseException):
    """A script tried to touch something outside the sandbox.

    Derives from :class:`BaseException` on purpose. A violation must not be
    swallowed by ``except Exception`` in user code — that would turn the jail
    into advice rather than a boundary.
    """


def _text(path):
    """The path as text, or None when it is a file descriptor."""
    if isinstance(path, str):
        return path
    if isinstance(path, bytes):
        return path.decode("utf-8", "replace")
    fspath = getattr(path, "__fspath__", None)
    if fspath is not None:
        return os.fspath(fspath)
    return None


def _under(roots, path):
    """True when [path] really is inside one of [roots] (symlinks resolved)."""
    real = os.path.realpath(path)
    for root in roots:
        if real == root or real.startswith(root + os.sep):
            return True
    return False


_WRITE_FLAGS = os.O_WRONLY | os.O_RDWR | os.O_APPEND | os.O_CREAT | os.O_TRUNC
_WRITE_MODES = frozenset("wax+")


class Jail:
    """Allows reads under `read_roots`, writes under `write_roots`.

    Use it as a context manager around the code that runs untrusted. Nested
    jails work: the inner one is restored on exit.
    """

    def __init__(self, read_roots, write_roots, blocked_hosts=()):
        self.read_roots = tuple(_abs_real(r) for r in read_roots)
        self.write_roots = tuple(_abs_real(r) for r in write_roots)
        self.blocked_hosts = tuple(blocked_hosts)
        self._previous = None

    def __enter__(self):
        global _ACTIVE
        _install()
        self._previous = _ACTIVE
        _ACTIVE = self
        return self

    def __exit__(self, *_exc):
        global _ACTIVE
        _ACTIVE = self._previous
        self._previous = None
        return False

    # -------------------------------------------------------------- checks

    def check_open(self, path, mode=None, flags=None):
        """`open(path, mode, flags)` — the mode or the flags say write or read."""
        if isinstance(mode, int):
            mode, flags = None, mode
        writes = bool(_WRITE_MODES & set(mode or "")) or (
            isinstance(flags, int) and bool(flags & _WRITE_FLAGS)
        )
        self.check_path(path, write=writes)

    def check_path(self, path, write=False):
        text = _text(path)
        if text is None:
            return  # a file descriptor: there is no name to check
        if write:
            if not _under(self.write_roots, text):
                raise SandboxViolation("запись за пределами рабочей папки запрещена: %s" % text)
            return
        if not _under(self.read_roots, text):
            raise SandboxViolation("чтение за пределами рабочей папки запрещено: %s" % text)

    def check_pair(self, src, dst, write_dst=True):
        self.check_path(src, write=False)
        if write_dst:
            self.check_path(dst, write=True)

    def check_address(self, host):
        if not host:
            return
        if host in self.blocked_hosts:
            raise SandboxViolation("подключение к %s запрещено" % host)

    def deny(self, what):
        raise SandboxViolation(what)


def _abs_real(path):
    return os.path.realpath(os.path.abspath(path))


# --------------------------------------------------------------------- hook

_ACTIVE = None
_HOOKED = False

_DENY = {
    "os.exec": "запуск процессов недоступен в песочнице",
    "os.posix_spawn": "запуск процессов недоступен в песочнице",
    "os.spawn": "запуск процессов недоступен в песочнице",
    "os.fork": "запуск процессов недоступен в песочнице",
    "os.forkpty": "запуск процессов недоступен в песочнице",
    "os.system": "запуск процессов недоступен в песочнице",
    "os.putenv": "изменение окружения недоступно в песочнице",
    "os.setuid": "смена пользователя недоступна в песочнице",
    "os.setgid": "смена группы недоступна в песочнице",
    "subprocess.Popen": "запуск процессов недоступен в песочнице",
    "pty.spawn": "запуск процессов недоступен в песочнице",
    "ctypes.dlopen": "нативный код недоступен в песочнице",
    "ctypes.dlsym": "нативный код недоступен в песочнице",
    "ctypes.call_function": "нативный код недоступен в песочнице",
    "ctypes.set_exception": "нативный код недоступен в песочнице",
}

_READ_EVENTS = ("os.listdir", "os.scandir", "os.chdir", "os.stat")
_WRITE_EVENTS = (
    "os.remove",
    "os.unlink",
    "os.rename",
    "os.replace",
    "os.mkdir",
    "os.rmdir",
    "os.chmod",
    "os.chown",
    "os.truncate",
    "os.link",
    "os.symlink",
)


def _audit(event, args):
    jail = _ACTIVE
    if jail is None:
        return
    denied = _DENY.get(event)
    if denied is not None:
        jail.deny(denied)
    if event == "open":
        jail.check_open(*args[:3])
    elif event == "os.rename":
        jail.check_pair(args[0], args[1], write_dst=True)
    elif event == "os.link":
        jail.check_path(args[0], write=False)
        jail.check_path(args[1], write=True)
    elif event == "os.symlink":
        jail.check_path(args[0], write=False)
        jail.check_path(args[1], write=True)
    elif event in _WRITE_EVENTS:
        jail.check_path(args[0], write=True)
    elif event in _READ_EVENTS:
        jail.check_path(args[0], write=False)
    elif event in ("socket.connect", "socket.bind"):
        address = args[1] if len(args) > 1 else None
        if isinstance(address, (str, bytes)):
            # A unix socket path, not an IP: it can reach any local service.
            jail.deny("unix-сокеты недоступны в песочнице")
        elif isinstance(address, tuple) and address:
            jail.check_address(address[0])


def _install():
    global _HOOKED
    if _HOOKED:
        return
    sys.addaudithook(_audit)
    _HOOKED = True


class _Intercept:
    """Context manager form of `Jail`, so callers can write `with intercept(...)`."""

    def __init__(self, jail):
        self._jail = jail

    def __enter__(self):
        self._jail.__enter__()
        return self._jail

    def __exit__(self, *exc):
        return self._jail.__exit__(*exc)


def intercept(read_roots, write_roots, blocked_hosts=()):
    return _Intercept(Jail(read_roots, write_roots, blocked_hosts))

"""Entry points that the Android side calls through Chaquopy.

Kotlin owns the UI, the sandbox and process lifetime; everything that only makes
sense in Python lives here: argv handling, sys.path setup, stream redirection and
traceback formatting.

User code runs inside the interpreter with the app's own uid, so `open` and `os`
would reach the activation key in shared_prefs and every other project. The
`pocketrun_sandbox` audit-hook jail is what keeps a script inside the workspace.
"""

import io
import json
import os
import runpy
import sys
import traceback

import pocketrun_sandbox

# Nothing here is reachable from a script: the loopback interface (the app's own
# java bridges and any local debug server), link-local addresses (cloud metadata)
# and unix sockets (any local service).
BLOCKED_HOSTS = ("localhost", "127.0.0.1", "::1", "0.0.0.0", "169.254.169.254")


class PipeStream:
    """A minimal text stream that appends to a file the Android side tails.

    Using a file rather than a pipe means slow readers can never stall the
    interpreter, and output survives a crash of the UI process.
    """

    def __init__(self, path, mirror=None):
        self._file = open(path, "a", encoding="utf-8", buffering=1, errors="replace")
        self._mirror = mirror

    encoding = "utf-8"
    errors = "replace"

    def write(self, text):
        if not isinstance(text, str):
            text = str(text)
        self._file.write(text)
        if self._mirror is not None:
            self._mirror.write(text)
        return len(text)

    def writelines(self, lines):
        for line in lines:
            self.write(line)

    def flush(self):
        self._file.flush()

    def isatty(self):
        return False

    def writable(self):
        return True

    def readable(self):
        return False

    def seekable(self):
        return False

    def close(self):
        try:
            self._file.close()
        except Exception:
            pass


def run(script, args_json, stdin_text, out_path, err_path, cwd, sandbox_root=None):
    """Runs ``script`` as __main__ and returns its exit code.

    ``sandbox_root`` is the workspace directory; the script may read the Python
    installation (stdlib, installed packages) but may only touch the workspace.
    """
    if not os.path.isfile(script):
        _write_line(err_path, "python: no such file: %s" % script)
        return 2

    try:
        args = json.loads(args_json) if args_json else []
    except ValueError as exc:
        _write_line(err_path, "python: invalid args json: %s" % exc)
        return 2
    if not isinstance(args, list):
        _write_line(err_path, "python: args json must be a list")
        return 2
    args = [str(arg) for arg in args]

    # The interpreter is process-wide, so every bit of global state we touch has
    # to go back to exactly what it was, or the next run inherits it.
    previous = (
        sys.stdout,
        sys.stderr,
        sys.stdin,
        sys.argv,
        os.getcwd(),
    )
    if cwd:
        try:
            os.chdir(cwd)
        except OSError as exc:
            _write_line(err_path, "python: cannot enter %s: %s" % (cwd, exc))
            return 2

    sys.argv = [script] + args
    script_dir = os.path.dirname(os.path.abspath(script))
    if script_dir not in sys.path:
        sys.path.insert(0, script_dir)

    if stdin_text is not None:
        sys.stdin = io.StringIO(stdin_text)

    out = PipeStream(out_path, previous[0])
    err = PipeStream(err_path, previous[1])
    sys.stdout, sys.stderr = out, err
    code = 0
    try:
        with pocketrun_sandbox.intercept(
            read_roots=_read_roots(sandbox_root or cwd),
            write_roots=[sandbox_root or cwd],
            blocked_hosts=BLOCKED_HOSTS,
        ):
            try:
                runpy.run_path(script, run_name="__main__")
            except SystemExit as exc:
                code = _exit_code(exc.code)
            except KeyboardInterrupt:
                _write_line(err_path, "KeyboardInterrupt")
                code = 130
            except BaseException:
                # SandboxViolation lands here too: the traceback is the report.
                traceback.print_exc(file=err)
                code = 1
    finally:
        # Restoring global state happens outside the jail: the previous working
        # directory is the app's own, and the jail would refuse to go back to it.
        sys.stdout, sys.stderr, sys.stdin, sys.argv = previous[:4]
        out.close()
        err.close()
        try:
            os.chdir(previous[4])
        except OSError:
            pass
    return code


def _read_roots(sandbox_root):
    """Where a script may read: the workspace plus the Python installation.

    Chaquopy unpacks the interpreter, the standard library and every pip
    package into the app's data directory, so the workspace alone is not enough
    to run anything.
    """
    roots = [sandbox_root]
    roots.extend(pocketrun_sandbox.interpreter_roots())
    return roots


def check_script(script):
    """Cheap syntax check so the editor can flag errors before a run."""
    if not os.path.isfile(script):
        return "no such file: %s" % script
    with open(script, "r", encoding="utf-8", errors="replace") as handle:
        source = handle.read()
    try:
        compile(source, os.path.basename(script), "exec")
        return None
    except SyntaxError as exc:
        return "line %s: %s" % (exc.lineno, exc.msg)
    except ValueError as exc:
        return str(exc)


def list_packages():
    """Installed distributions, for the packages screen."""
    try:
        from importlib import metadata
    except ImportError:
        return []
    found = []
    for dist in metadata.distributions():
        try:
            name = dist.metadata["Name"]
            if not name:
                continue
            found.append({"name": name, "version": dist.version or "?"})
        except Exception:
            continue
    found.sort(key=lambda item: item["name"].lower())
    return found


def interpreter_info():
    return {
        "version": sys.version.split()[0],
        "implementation": sys.implementation.name,
        "executable": sys.executable,
        "path": sys.path[:],
    }


def _exit_code(value):
    if value is None:
        return 0
    if isinstance(value, bool):
        return 1 if value else 0
    if isinstance(value, int):
        return value
    _write_line_to_stderr("SystemExit: %s" % (value,))
    return 1


def _write_line(path, text):
    _write_line_to_stderr(text, path)


def _write_line_to_stderr(text, path=None):
    if path:
        with open(path, "a", encoding="utf-8") as handle:
            handle.write(text + "\n")
    else:
        # sys.__stderr__ is None on builds where stderr is not connected.
        stream = sys.__stderr__
        if stream is None:
            return
        try:
            stream.write(text + "\n")
            stream.flush()
        except Exception:
            pass

package dev.pocketrun.runtime.python

import android.content.Context
import android.util.Log
import com.chaquo.python.Python
import com.chaquo.python.android.AndroidPlatform
import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.ExecRequest
import dev.pocketrun.runtime.ExecResult
import dev.pocketrun.runtime.ExecutionHandle
import dev.pocketrun.runtime.OutputListener
import dev.pocketrun.runtime.OutputTailer
import dev.pocketrun.runtime.OutputStream
import java.io.File
import java.util.UUID
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean

/**
 * The CPython runtime. Chaquopy keeps one interpreter per process, so it is
 * started once from [initAsync] (about a second; never on the main thread) and
 * every [execute] afterwards reuses it.
 *
 * Scripts talk to the UI through files, not pipes: the Python bootstrap
 * (pocketrun.py) appends stdout/stderr to log files in the workspace cache and
 * two [OutputTailer]s stream them back as text.
 */
object PythonRuntime {

    private const val TAG = "PythonRuntime"
    private const val MAX_CAPTURE = 256 * 1024
    private const val TAILER_JOIN_MS = 2_000L

    private val lock = Any()

    @Volatile private var python: Python? = null
    @Volatile private var version: String? = null
    @Volatile private var workspace: Workspace? = null

    private val executor: ExecutorService = Executors.newSingleThreadExecutor { runnable ->
        Thread(runnable, "pocketrun-python-run").apply { isDaemon = true }
    }

    /** Starts CPython once. Safe to call again; returns immediately. */
    fun initAsync(context: Context) {
        if (python != null) return
        Thread({
            try {
                synchronized(lock) {
                    if (python == null) {
                        val appContext = context.applicationContext
                        Python.start(AndroidPlatform(appContext))
                        val py = Python.getInstance()
                        workspace = Workspace.from(appContext)
                        version = readVersion(py)
                        python = py
                        Log.i(TAG, "Python started ($version)")
                    }
                }
            } catch (t: Throwable) {
                Log.e(TAG, "Python failed to start", t)
            }
        }, "pocketrun-python-start").apply { isDaemon = true }.start()
    }

    fun isAvailable(): Boolean = python != null

    fun version(): String? = version

    private fun readVersion(py: Python): String? = try {
        py.getModule("pocketrun")
            .callAttr("interpreter_info")
            .get("version")
            .toString()
    } catch (t: Throwable) {
        Log.w(TAG, "interpreter_info failed", t)
        null
    }

    /**
     * Runs [request.target] with CPython. [listener.onOutput] arrives from the
     * tailer threads; [listener.onFinished] / [listener.onFailed] arrive from
     * the single run thread.
     *
     * The target and the working directory are resolved through
     * [Workspace.resolve] first, so a script can only ever be one of the files
     * inside the sandbox; the Python side repeats the check with an audit-hook
     * jail for everything the script does itself.
     *
     * Cancellation is cooperative: Chaquopy cannot interrupt a call, so
     * [ExecutionHandle.cancel] only raises a flag, and the result is reported
     * with exit code 130 (SIGINT) once the script returns on its own.
     */
    fun execute(request: ExecRequest, listener: OutputListener): ExecutionHandle {
        val py = python
        val stopped = AtomicBoolean(false)
        val cancelled = AtomicBoolean(false)
        val running = AtomicBoolean(true)
        if (py == null) {
            running.set(false)
            listener.onFailed(IllegalStateException("Python is not running (yet)"))
            return Handle(running, cancelled)
        }

        val sandbox = workspace
        if (sandbox == null) {
            running.set(false)
            listener.onFailed(IllegalStateException("Python is not running (yet)"))
            return Handle(running, cancelled)
        }
        val cwd = request.cwd?.let { sandbox.resolve(it.absolutePath) } ?: sandbox.root
        val target = sandbox.resolve(request.target, cwd)
        if (target == null) {
            running.set(false)
            listener.onFailed(IllegalArgumentException("путь вне рабочей папки отклонён: ${request.target}"))
            return Handle(running, cancelled)
        }

        val startedAt = System.currentTimeMillis()
        val runDir = File(sandbox.cache, "runs/${UUID.randomUUID()}").apply { mkdirs() }
        val outFile = File(runDir, "out.log")
        val errFile = File(runDir, "err.log")
        val stdout = Capture()
        val stderr = Capture()

        val outTailer = OutputTailer(outFile, OutputStream.STDOUT, CaptureListener(listener, stdout), stopped) {}
        val errTailer = OutputTailer(errFile, OutputStream.STDERR, CaptureListener(listener, stderr), stopped) {}
        outTailer.start()
        errTailer.start()

        executor.execute {
            try {
                val argsJson = org.json.JSONArray().apply { request.args.forEach { put(it) } }.toString()
                val exitCode = py.getModule("pocketrun").callAttr(
                    "run",
                    target.absolutePath,
                    argsJson,
                    request.stdin,
                    outFile.absolutePath,
                    errFile.absolutePath,
                    cwd.absolutePath,
                    sandbox.root.absolutePath,
                ).toInt()

                stopped.set(true)
                outTailer.join(TAILER_JOIN_MS)
                errTailer.join(TAILER_JOIN_MS)

                listener.onFinished(
                    ExecResult(
                        exitCode = if (cancelled.get()) 130 else exitCode,
                        stdout = stdout.text(),
                        stderr = stderr.text(),
                        durationMs = System.currentTimeMillis() - startedAt,
                        truncated = stdout.truncated || stderr.truncated,
                    ),
                )
            } catch (t: Throwable) {
                stopped.set(true)
                try {
                    outTailer.join(TAILER_JOIN_MS)
                    errTailer.join(TAILER_JOIN_MS)
                } catch (_: InterruptedException) {
                    Thread.currentThread().interrupt()
                }
                listener.onFailed(t)
            } finally {
                running.set(false)
                runDir.deleteRecursively()
            }
        }
        return Handle(running, cancelled)
    }

    /**
     * Runs [request] to completion (waiting for the worker) and returns the
     * result. On timeout the run is flagged cancelled and a 124 result is
     * returned. Used by the agent's run_python tool.
     */
    fun executeSync(request: ExecRequest, timeoutMs: Long): ExecResult {
        val done = java.util.concurrent.CompletableFuture<ExecResult>()
        val handle = execute(request, object : OutputListener {
            override fun onFinished(result: ExecResult) { done.complete(result) }
            override fun onFailed(error: Throwable) { done.completeExceptionally(error) }
        })
        return try {
            done.get(timeoutMs, java.util.concurrent.TimeUnit.MILLISECONDS)
        } catch (e: java.util.concurrent.TimeoutException) {
            handle.cancel()
            ExecResult(124, "", "превышено время выполнения (${timeoutMs / 1000} с)", timeoutMs)
        } catch (e: java.util.concurrent.ExecutionException) {
            ExecResult(1, "", e.cause?.message ?: e.message ?: "ошибка запуска", 0)
        }
    }

    /** Forwards tailer output and keeps a capped copy for the final ExecResult. */
    private class CaptureListener(
        private val downstream: OutputListener,
        private val capture: Capture,
    ) : OutputListener {
        override fun onOutput(stream: OutputStream, text: String) {
            capture.append(text)
            downstream.onOutput(stream, text)
        }
    }

    private class Capture {
        private val builder = StringBuilder()
        var truncated = false
            private set

        fun append(text: String) {
            if (truncated) return
            val room = MAX_CAPTURE - builder.length
            if (room <= 0) {
                truncated = true
                return
            }
            if (text.length <= room) {
                builder.append(text)
            } else {
                builder.append(text, 0, room)
                truncated = true
            }
        }

        fun text(): String = builder.toString()
    }

    private class Handle(
        private val running: AtomicBoolean,
        private val cancelled: AtomicBoolean,
    ) : ExecutionHandle {
        override val isRunning: Boolean get() = running.get()
        override fun cancel() = cancelled.set(true)
    }
}

package dev.pocketrun.license

import android.content.Context
import android.content.SharedPreferences
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * Holds the activated key and exposes it as observable state. The key is
 * re-verified on every launch and whenever the user pastes a new one; nothing is
 * cached as "already validated".
 *
 * Verification uses [MonotonicClock], so turning the device clock back cannot
 * bring an expired key back to life.
 */
class LicenseManager(
    context: Context,
    private val publicKey: String,
    private val clock: MonotonicClock = MonotonicClock.forContext(context),
) {
    private val prefs: SharedPreferences =
        context.applicationContext.getSharedPreferences("license", Context.MODE_PRIVATE)

    private val _state = MutableStateFlow(evaluate())
    val state: StateFlow<LicenseState> = _state.asStateFlow()

    sealed interface LicenseState {
        data object NeedsActivation : LicenseState
        data class Active(
            val claims: LicenseFormat.Claims,
            val fingerprint: String,
            val daysRemaining: Long?,
        ) : LicenseState {
            val canUseAgent: Boolean get() = claims.plan in AGENT_PLANS
        }

        data class Rejected(val message: String) : LicenseState
    }

    /** Accepts a pasted key. Returns true when it verified. */
    fun activate(rawKey: String): Boolean {
        val key = LicenseFormat.normalize(rawKey)
        if (key.isEmpty()) {
            _state.value = LicenseState.Rejected("Enter a license key.")
            return false
        }
        return when (val outcome = LicenseVerifier.verify(key, publicKey, clock.now())) {
            is LicenseVerifier.Outcome.Valid -> {
                prefs.edit().putString(KEY, key).apply()
                _state.value = LicenseState.Active(
                    claims = outcome.claims,
                    fingerprint = outcome.keyFingerprint,
                    daysRemaining = LicenseVerifier.daysRemaining(outcome.claims, clock.now()),
                )
                true
            }

            is LicenseVerifier.Outcome.Expired -> {
                _state.value = LicenseState.Rejected("This license expired.")
                false
            }

            is LicenseVerifier.Outcome.NotYetValid -> {
                _state.value = LicenseState.Rejected("This license is not valid yet.")
                false
            }

            is LicenseVerifier.Outcome.Rejected -> {
                _state.value = LicenseState.Rejected(outcome.reason)
                false
            }
        }
    }

    fun forget() {
        prefs.edit().remove(KEY).apply()
        _state.value = LicenseState.NeedsActivation
    }

    private fun evaluate(): LicenseState {
        val stored = prefs.getString(KEY, null)
        if (stored.isNullOrBlank()) return LicenseState.NeedsActivation
        return when (val outcome = LicenseVerifier.verify(stored, publicKey, clock.now())) {
            is LicenseVerifier.Outcome.Valid -> LicenseState.Active(
                claims = outcome.claims,
                fingerprint = outcome.keyFingerprint,
                daysRemaining = LicenseVerifier.daysRemaining(outcome.claims, clock.now()),
            )

            is LicenseVerifier.Outcome.Expired ->
                LicenseState.Rejected(
                    "This license expired on " +
                        java.time.Instant.ofEpochSecond(outcome.claims.expiresAt) + ".",
                )

            is LicenseVerifier.Outcome.NotYetValid ->
                LicenseState.Rejected("This license is not valid yet.")

            is LicenseVerifier.Outcome.Rejected -> LicenseState.Rejected(outcome.reason)
        }
    }

    companion object {
        private const val KEY = "key"
        private val AGENT_PLANS = setOf("pro", "team", "lifetime")
    }
}

